console.log("Step 1: Listing available filenames...");
const filenames = Object.keys(data || {});
console.log("Filenames found:", filenames);

console.log("Step 2: Locating Questionnaire table...");
const questionnaireFilename = filenames.find(name => name.toLowerCase().includes("prod_nirman_questionnaire"));
console.log("Questionnaire filename:", questionnaireFilename);

console.log("Step 3: Counting total response rows...");
const questionnaireRows = Array.isArray(data[questionnaireFilename]) ? data[questionnaireFilename] : [];
const totalResponseRows = questionnaireRows.length;
console.log("Total response rows in Questionnaire:", totalResponseRows);

console.log("Step 4: Returning answers...");
return {
  summary: {
    total_survey_responses: totalResponseRows,
    table_used: "Questionnaire",
    grain: "1 row per (Participant_Id, Workshop_Level, Workshop_Phase)"
  }
};
